# Lunar Konstruksi - Fase 7.1 Design Reset
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Fail([string]$Message) { Write-Host "[FASE 7.1] GAGAL: $Message" -ForegroundColor Red; exit 1 }
function Write-Utf8NoBom([string]$Path,[string]$Content){$parent=Split-Path -Parent $Path;if($parent -and -not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Force -Path $parent|Out-Null};$enc=New-Object System.Text.UTF8Encoding($false);[System.IO.File]::WriteAllText($Path,$Content,$enc)}
function Decode([string]$Value){[System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))}

$repoRoot=(& git rev-parse --show-toplevel 2>$null);if(-not $repoRoot){Fail "Jalankan dari root repository."};$repoRoot=$repoRoot.Trim();Set-Location $repoRoot
$required=@("components/site/redesign/public-page-renderer.tsx","components/site/redesign/public-header.tsx","components/site/redesign/public-footer.tsx","features/public-site/public-site.types.ts","features/public-site/public-site.service.ts")
$missing=@($required|Where-Object{-not(Test-Path -LiteralPath $_)});if($missing.Count -gt 0){$missing|ForEach-Object{Write-Host " - $_"};Fail "Fase 7 belum lengkap."}
$payload=@{}
$payload["PHASE7_1_DESIGN_RESET.md"]=""
$payload["components/site/redesign/public-contact-form.tsx"]=""
$payload["components/site/redesign/public-footer.tsx"]=""
$payload["components/site/redesign/public-header.tsx"]=""
$payload["components/site/redesign/public-page-renderer.tsx"]=""
foreach($entry in $payload.GetEnumerator()){$target=Join-Path $repoRoot $entry.Key;Write-Utf8NoBom $target (Decode $entry.Value);Write-Host "[FASE 7.1] write $($entry.Key)" -ForegroundColor DarkGray}
Write-Host "";Write-Host "[FASE 7.1] Design reset selesai." -ForegroundColor Green;Write-Host "Tidak ada dependency baru." -ForegroundColor Green;Write-Host "Jalankan: npm run dev" -ForegroundColor Cyan
